<script setup lang="ts">
import { onMounted, reactive, ref } from "vue";
import { ElMessage } from "element-plus";
import { Plus, RefreshRight } from "@element-plus/icons-vue";
import { http } from "@/api/http";
import { qualityRiskApi } from "@/api/quality-risk.api";
import { useAuthStore } from "@/stores/auth.store";
import { useQualityReferenceStore } from "@/stores/quality-reference.store";

const auth=useAuthStore();const refs=useQualityReferenceStore();const rows=ref<any[]>([]);const standards=ref<any[]>([]);const loading=ref(false);const dialog=ref(false);
const form=reactive({code:"",name:"",version:"v1",standard_id:"",clause_ref:"",page_ref:"",category_id:"",product_id:"",indicator:"",method:"",unit:"",operator:"lte",threshold:0,decision_action:"fail",manual_review:true});
async function load(){loading.value=true;try{const [rules,standardResult]=await Promise.all([qualityRiskApi.standardRules(),http.get<any>("/v1/inspection-standards",{params:{size:200}}),refs.loadProducts()]);rows.value=rules.data.data;standards.value=standardResult.data.data.items||[];}finally{loading.value=false}}
function open(){Object.assign(form,{code:"",name:"",version:"v1",standard_id:standards.value[0]?.id||"",clause_ref:"",page_ref:"",category_id:"",product_id:"",indicator:"",method:"",unit:"",operator:"lte",threshold:0,decision_action:"fail",manual_review:true});dialog.value=true}
async function save(){if(!form.code||!form.name||!form.standard_id||!form.clause_ref||!form.indicator){ElMessage.warning("请补全编码、名称、标准、条款和指标");return}await qualityRiskApi.createStandardRule({code:form.code,name:form.name,version:form.version,standard_id:form.standard_id,clause_ref:form.clause_ref,page_ref:form.page_ref||null,category_id:form.category_id||null,product_id:form.product_id||null,indicator:form.indicator,method:form.method||null,unit:form.unit||null,condition:{operator:form.operator,threshold:form.threshold},decision_action:form.decision_action,review_policy:{manual_review:form.manual_review}});dialog.value=false;ElMessage.success("标准执行规则草稿已创建");await load()}
async function publish(row:any){await qualityRiskApi.publishStandardRule(row.id);ElMessage.success("规则已发布");await load()}
onMounted(load);
</script>
<template><main class="rule-page"><header><div><p>STANDARD TO EXECUTION</p><h1>标准执行规则</h1><span>将权威标准条款转成可执行条件，每条规则保留标准、条款、页码和复核策略。</span></div><div><el-button :icon="RefreshRight" @click="load">刷新</el-button><el-button v-if="['admin','expert'].includes(auth.role)" type="primary" :icon="Plus" @click="open">新建规则</el-button></div></header><el-alert type="warning" :closable="false" title="规则适用于产品类别或具体产品；未知生产批次不阻塞判定，专项批次要求应作为来源证据单独记录。"/><el-table :data="rows" v-loading="loading"><el-table-column prop="code" label="规则编码" width="150"/><el-table-column prop="name" label="名称" min-width="180"/><el-table-column prop="clause_ref" label="标准条款" min-width="180"/><el-table-column prop="indicator" label="指标" width="130"/><el-table-column label="条件" min-width="150"><template #default="{row}">{{row.condition.operator}} {{row.condition.threshold}} {{row.unit||''}}</template></el-table-column><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.status==='published'?'success':'info'">{{row.status==='published'?'已发布':'草稿'}}</el-tag></template></el-table-column><el-table-column width="90"><template #default="{row}"><el-button v-if="auth.role==='admin'&&row.status!=='published'" link @click="publish(row)">发布</el-button></template></el-table-column></el-table><el-dialog v-model="dialog" title="新建标准执行规则" width="min(820px,95vw)" top="3vh"><el-form label-position="top"><div class="grid"><el-form-item label="规则编码" required><el-input v-model="form.code"/></el-form-item><el-form-item label="规则名称" required><el-input v-model="form.name"/></el-form-item><el-form-item label="版本"><el-input v-model="form.version"/></el-form-item><el-form-item label="检测标准" required><el-select v-model="form.standard_id"><el-option v-for="item in standards" :key="item.id" :label="item.name" :value="item.id"/></el-select></el-form-item><el-form-item label="条款号" required><el-input v-model="form.clause_ref"/></el-form-item><el-form-item label="页码"><el-input v-model="form.page_ref"/></el-form-item><el-form-item label="产品类别"><el-select v-model="form.category_id" clearable @change="form.product_id=''"> <el-option v-for="item in refs.categories" :key="item.id" :label="item.name" :value="item.id"/></el-select></el-form-item><el-form-item label="具体产品"><el-select v-model="form.product_id" clearable><el-option v-for="item in refs.products.filter(x=>!form.category_id||x.category_id===form.category_id)" :key="item.id" :label="item.name" :value="item.id"/></el-select></el-form-item><el-form-item label="检测/风险指标" required><el-input v-model="form.indicator"/></el-form-item><el-form-item label="检测方法"><el-input v-model="form.method"/></el-form-item><el-form-item label="单位"><el-input v-model="form.unit"/></el-form-item><el-form-item label="比较符"><el-select v-model="form.operator"><el-option label="小于等于" value="lte"/><el-option label="大于等于" value="gte"/><el-option label="等于" value="eq"/><el-option label="包含" value="contains"/></el-select></el-form-item><el-form-item label="阈值"><el-input-number v-model="form.threshold" :controls="false"/></el-form-item><el-form-item label="不满足时"><el-select v-model="form.decision_action"><el-option label="不通过" value="fail"/><el-option label="预警" value="warn"/><el-option label="人工复核" value="manual_review"/></el-select></el-form-item></div><el-switch v-model="form.manual_review" active-text="结论进入人工复核"/></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存草稿</el-button></template></el-dialog></main></template>
<style scoped>.rule-page{max-width:1440px;margin:0 auto;padding:24px}.rule-page>header{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;padding:28px;margin-bottom:14px;border:1px solid #e2d8c8;border-radius:16px;background:linear-gradient(120deg,#fff8ec,#fff 65%,#eef8f7)}header p{margin:0 0 8px;color:#af5c0d;font:700 11px ui-monospace,monospace;letter-spacing:.14em}h1{margin:0;font-size:36px}header span{display:block;margin-top:9px;color:#667a86}header>div:last-child{display:flex;gap:8px}.el-alert{margin-bottom:14px}.el-table{border:1px solid #e3e8eb;border-radius:14px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0 16px}.el-select,.el-input-number{width:100%}@media(max-width:800px){.grid{grid-template-columns:1fr 1fr}.rule-page>header{align-items:flex-start;flex-direction:column}}@media(max-width:520px){.rule-page{padding:12px}.grid{grid-template-columns:1fr}}</style>
